'use strict';
const MODE_KEY='horar.tabs.v1';let modeState;try{modeState=HorarSession.create(JSON.parse(sessionStorage.getItem(MODE_KEY)||'null'));}catch{modeState=HorarSession.create();}
let restoringMode=false;
const modeFields=['question','moment','offset','lat','lon','system','target','city','place-search','topic-mode','actor-input','horizon'];
function draft(){return {fields:Object.fromEntries(modeFields.map(id=>[id,$(id).value])),place:selectedPlace,manualZone};}
function persistModes(){try{sessionStorage.setItem(MODE_KEY,JSON.stringify(modeState));}catch{}}
function setDraft(d){if(!d?.fields)return;for(const id of modeFields)if(typeof d.fields[id]==='string')$(id).value=d.fields[id];selectedPlace=d.place||null;manualZone=d.manualZone===true;cityOffset();$('offset').value=d.fields.offset;$('place-selected').textContent=selectedPlace?placeLabel(selectedPlace):'Координаты вручную';$('place-results').hidden=true;searchSequence++;$('place-status').textContent='';$('error').textContent='';classifyDraft();}
function restoreAnalysisFields(i){$('target').disabled=i.analysisVersion===2&&i.topicMode==='auto'&&Boolean(HorarAnalysis.classify(i.question).house);$('topic-mode').value=i.analysisVersion===2?(i.topicMode||'manual'):'manual';$('actor-input').value=i.actorInput||'auto';$('horizon').value=String(i.horizon||30);}
function classifyDraft(){const ctx=HorarAnalysis.classify($('question').value),auto=$('topic-mode').value==='auto';if(auto&&ctx.house){const prepared=HorarAnalysis.prepare({question:$('question').value,target:Number($('target').value),topicMode:'auto',actorInput:$('actor-input').value});$('target').value=String(prepared.target);}$('target').disabled=auto&&!!ctx.house;$('classification').textContent=auto?ctx.reason+' Участник: '+($('actor-input').value==='auto'?ctx.actorLabel:$('actor-input').selectedOptions[0].textContent)+'. Итоговый дом: '+$('target').value+'.':'Дом выбран вручную; поле «О ком вопрос» применяется в автоматическом режиме.';topicHelp();}
function drawAnalysis(c){const a=c.analysis;$('analysis-detail').hidden=!a;if(!a)return;const time=t=>localTime(t,c.input.offset);$('analysis-detail').innerHTML=`<p class="eyebrow">ОСНОВАНИЯ СУЖДЕНИЯ</p><h3>${escape(c.verdict)}</h3><p>${escape(a.context.label)} · участник ${a.actorHouse} дом · цель ${c.input.target} дом · поиск ${a.days} дней</p><details open><summary>Поддержка: ${a.support} · препятствия: ${a.obstacles}</summary><p class="hint">Количество правил, не вероятность. Некоторые показатели связаны между собой.</p>${a.evidence.map(x=>`<p><b>${x.direction==='support'?'Поддержка':x.direction==='obstacle'?'Препятствие':'Контекст'}.</b> ${escape(x.text.replace(/\d{4}-\d{2}-\d{2}T[\d:.]+Z/g,time))}</p>`).join('')}</details><details><summary>Семь соображений перед суждением</summary>${a.checks.map(x=>`<p><b>${x.active?'△':'✓'} ${escape(x.label)}</b> — ${escape(x.detail)}</p>`).join('')}</details><details><summary>Ближайшие события и изменения условий</summary>${a.events.slice(0,12).map(x=>`<p>${escape(time(x.utc))}: ${H.names[x.i]} — ${H.names[x.j]}, ${x.name}</p>`).join('')}${a.changes.slice(0,10).map(x=>`<p>${escape(time(x.utc))}: ${H.names[x.i]}, ${x.type==='ingress'?'смена знака':'станция'}</p>`).join('')}<p class="hint">Это моменты движения планет, не назначенные даты жизненных событий.</p></details>`;}
function topicHelp(){const t=HorarSimple.topics[$('target').value];$('topic-help').textContent=t[2]+' Например: «'+t[1]+'»';}
function drawSimple(c){const s=HorarSimple.explain(c);$('simple-reading').innerHTML=`<article class="reading-main"><p class="eyebrow">ПОНЯТНЫЙ ИТОГ</p><h2>${escape(s.title)}</h2><p>${escape(s.summary)}</p></article><div class="notice">Это символический разбор по правилам хорара, а не достоверный прогноз будущего.</div>`+s.sections.map(x=>`<article class="panel simple-section"><h3>${escape(x.title)}</h3>${x.paragraphs.map(p=>`<p>${escape(p)}</p>`).join('')}</article>`).join('');}
function modeLook(){const beginner=modeState.mode==='beginner';document.body.dataset.mode=modeState.mode;document.querySelectorAll('[data-mode-tab]').forEach(b=>{const active=b.dataset.modeTab===modeState.mode;b.setAttribute('aria-selected',String(active));b.classList.toggle('active',active);});$('advanced-input').open=!beginner;$('simple-reading').hidden=!beginner;$('technical-reading').hidden=beginner;$('mode-caption').textContent=beginner?'Понятный итог и подробное объяснение. Точные таблицы находятся во вкладке «Для профи».':'Положения планет, дома, аспекты, рецепции и основания традиционной интерпретации.';for(const o of $('target').options){if(!o.dataset.full)o.dataset.full=o.textContent;o.textContent=beginner?HorarSimple.topics[o.value][0]:o.dataset.full;}$('calculate').innerHTML=beginner?'Разобрать мой вопрос <span>↗</span>':'Построить и разобрать <span>↗</span>';topicHelp();}
const originalRender=render;
render=function(c){restoreAnalysisFields(c.input);drawAnalysis(c);if(!c.lunar)c.lunar=H.lunarEvents(c);if(!restoringMode){HorarSession.commit(modeState,c.input,draft(),currentId);persistModes();}originalRender(c);drawSimple(c);$('result-question').textContent=c.input.question;$('result-context').textContent=localTime(c.date,c.input.offset)+' · '+(c.input.place?placeLabel(c.input.place):`${c.input.lat}°, ${c.input.lon}°`);$('share-panel').hidden=true;modeLook();};
function switchMode(mode){if(mode===modeState.mode)return;modeState.slots[modeState.mode].draft=draft();modeState.slots[modeState.mode].id=currentId;modeState.mode=mode;const slot=modeState.slots[mode];setDraft(slot.draft);currentId=slot.id;restoringMode=true;try{if(slot.input)render(H.calculate(slot.input));else{current=null;currentId=null;$('results').hidden=true;wheel(null);$('chart-title').textContent='Карта появится здесь';$('chart-caption').textContent='В этой вкладке ещё нет расчёта.';}}finally{restoringMode=false;}modeLook();persistModes();}
for(const button of document.querySelectorAll('[data-mode-tab]'))button.onclick=()=>switchMode(button.dataset.modeTab);
$('chart-form').addEventListener('input',()=>{modeState.slots[modeState.mode].draft=draft();persistModes();});
$('target').addEventListener('change',topicHelp);for(const id of ['question','topic-mode','actor-input'])$(id).addEventListener('input',classifyDraft);
$('place-clear').addEventListener('click',()=>{$('advanced-input').open=true;});
function resetSession(){if(!confirm('Начать новый сеанс вкладок? Текущие черновики и результаты вкладок будут сброшены. Сохранённый журнал останется.'))return;modeState=HorarSession.create();current=null;currentId=null;$('question').value='';$('topic-mode').value='auto';$('actor-input').value='auto';$('horizon').value='30';classifyDraft();now();modeState.slots.beginner.draft=draft();modeState.slots.pro.draft=draft();$('results').hidden=true;wheel(null);$('chart-title').textContent='Карта появится здесь';$('chart-caption').textContent='Введите вопрос, чтобы увидеть реальные положения планет.';modeLook();persistModes();}
$('reset-session').onclick=resetSession;
$('share-result').onclick=()=>{if(!current)return;try{const url=HorarShare.url(current.input);$('share-url').value=url;$('share-link').href=url;$('share-panel').hidden=false;notify('share-status','Ссылка готова. В ней есть вопрос, время и место. Передавайте её только тем, кому хотите показать эти данные.');}catch(e){notify('status',e.message);}};
$('copy-share').onclick=async()=>{try{if(window.Android?.copyLink)Android.copyLink($('share-url').value);else await navigator.clipboard.writeText($('share-url').value);notify('share-status','Ссылка скопирована.');}catch{$('share-url').focus();$('share-url').select();notify('share-status','Не удалось скопировать автоматически. Ссылка выделена — выберите «Копировать».');}};
$('send-share').onclick=async()=>{if(window.Android?.shareLink){Android.shareLink($('share-url').value);return;}if(!navigator.share){$('copy-share').click();return;}try{await navigator.share({title:'Хорар — разбор вопроса',url:$('share-url').value});}catch(e){if(e.name!=='AbortError')notify('share-status','Не удалось открыть отправку. Скопируйте ссылку кнопкой рядом.');}};
if(!modeState.slots.beginner.draft){modeState.slots.beginner.draft=draft();modeState.slots.pro.draft=draft();}
const initialSlot=modeState.slots[modeState.mode];try{setDraft(initialSlot.draft);if(initialSlot.input){currentId=initialSlot.id;restoringMode=true;render(H.calculate(initialSlot.input));}}catch{modeState=HorarSession.create();}finally{restoringMode=false;}
modeLook();classifyDraft();
function openShared(){if(!location.hash.startsWith('#result='))return;try{const i=HorarShare.parse(location.hash);for(const id of ['question','offset','lat','lon','system','target','city'])$(id).value=i[id];$('moment').value=i.local;restorePlace(i);restoreAnalysisFields(i);currentId=null;render(H.calculate(i));page('workspace');notify('status','Открыт результат по ссылке. Он не добавлен в журнал — сохраните его при необходимости.');}catch(e){notify('error','Ссылка не открыта: '+e.message);}}
openShared();window.addEventListener('hashchange',openShared);
window.addEventListener('pagehide',()=>{modeState.slots[modeState.mode].draft=draft();modeState.slots[modeState.mode].id=currentId;persistModes();});
